[
  {
    "statement": "Several alternative treatments and seeding methods beyond fertilizer application have been studied for increasing vegetation cover on degraded land.",
    "citations": []
  },
  {
    "statement": "Hydroseeding involves spraying a slurry of seed, mulch and water.",
    "citations": []
  },
  {
    "statement": "One study found that hydroseeding with non-native seeds increased overall plant cover in most cases.",
    "citations": [
      "3412"
    ]
  },
  {
    "statement": "Sowing seeds at a higher density can increase grass and forb cover.",
    "citations": [
      "3405"
    ]
  },
