    "citations": [
      "3431"
    ]
  },
  {
    "statement": "Irrigation after seeding increased vegetation cover in six of 10 cases when using non-native seeds.",
    "citations": [
      "3430"
    ]
  },
  {
    "statement": "A study showed that higher species diversity in seed mixes increased the cover of sown plant species.",
    "citations": [
      "3406"
    ]
  },
