[
  {
    "statement": "The available evidence on nurse plants for improving grassland plant community composition and richness shows mixed and generally limited effectiveness.",
    "citations": []
  },
  {
    "statement": "One replicated, controlled study in France found that sowing seeds of nurse plants reduced the similarity of the plant community to that of nearby intact steppe compared to areas where no seeds were sown.",
    "citations": [
      "3401"
    ]
  },
  {
    "statement": "The same study in France found that sowing seeds of nurse plants did not change plant species richness.",
    "citations": [
      "3401"
    ]
  },
  {
    "statement": "The study in France also found that plant species richness was lower than in nearby intact steppe.",
    "citations": [
      "3401"
    ]
  },
  {
    "statement": "One replicated, controlled study in Slovenia found that sowing a seed mix containing nurse species resulted in a community composition that was less similar to the target community when compared to sowing a seed mix that did not contain nurse species.",
    "citations": [
      "3402"
    ]
  },
  {
    "statement": "The Slovenia study also found that sowing a seed mix containing nurse species did not increase species richness compared to sowing a seed mix that did not contain nurse species.",
    "citations": [
      "3402"
    ]
  },
  {
    "statement": "A replicated, paired, controlled study in the USA found that sowing seeds of nurse plants alongside that of grassland species did not change grass abundance or forb abundance.",
    "citations": [
      "3402"
    ]
  },
  {
    "statement": "Nurse plants showed some benefits for plant establishment.",
    "citations": [
      "3402"
    ]
  },
  {
    "statement": "One replicated, controlled study in Spain found that sowing seeds under nurse plants increased seed germination.",
    "citations": [
      "3402"
    ]
  },
  {
    "statement": "For survival outcomes, one of two replicated, controlled studies in Kenya and Spain found that sowing seeds or planting under nurse plants increased survival of planted plants.",
    "citations": [
      "3402"
    ]
  },
  {
    "statement": "The other of two studies found that sowing seeds under nurse plants initially increased seedling survival, but there was no difference in survival after two to three years.",
    "citations": [
      "3402"
    ]
  }
]

[
  {
    "statement": "Evidence from grassland seeding projects shows mixed results for long-term effectiveness in improving plant community composition and vegetation cover.",
